%[text] # Matrix Vector Multiplication
%[text]{"align":"center"} $Ax = b$
Theta = linspace(0,2*pi);
x = 5*cos(Theta);
y = 5*sin(Theta);

plot(x,y) %[output:64e7f026]
hold on %[output:64e7f026]
scatter(x(1),y(1),30,"filled",SeriesIndex=1) %[output:64e7f026]
axis equal; % Set equal scaling for both axes %[output:64e7f026]
xlabel('X-axis'); %[output:64e7f026]
ylabel('Y-axis'); %[output:64e7f026]
title('Unit Circle'); %[output:64e7f026]
A = [1 2; 3 10000];
for k = 1:length(x)
    vec = [x(k); y(k)];
    newvec = A*vec;
    xx(k) = newvec(1);
    yy(k) = newvec(2);
end



plot(xx,yy,SeriesIndex=2) %[output:64e7f026]
scatter(xx(1),yy(1),30,"filled",SeriesIndex=2) %[output:64e7f026]
hold off %[output:64e7f026]
cond(A) %[output:63cbbab7]

